``parse_payment`` authenticates a provider delivery and normalizes it for the
account-crediting worker.  Two authentication paths are supported during the
provider notification migration:

``v1`` (current clients)
    ``X-Pay-Signature: v1=<hex>`` where the hex digest is HMAC-SHA256 over
    ``<ascii timestamp> + b"." + <exact received body bytes>``.

``r0`` (installed v0 connector / legacy receipts)
    ``X-Pay-Receipt: r0=<hex>`` where the hex digest is HMAC-SHA256 over
    ``<ascii timestamp> + b"." + <utf-8 event_id>``.  The v0 edge relay
    associates the receipt with the original message before forwarding, so a
    v0 delivery can reach us with a reformatted body and therefore no usable
    v1 body digest.  The receipt is the connector's stable identity proof
    across forwarding formats; the receipt path is only consulted when the v1
    path is absent or does not match.  It requires no provider round trip and
    no second message fingerprint, neither of which the installed connector
    can supply.

Both paths use the same shared secret and both require an in-window
``X-Pay-Timestamp``.  Payload field validation and the returned shape are
identical for the two paths.
"""

import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

#: Maximum accepted absolute clock skew, in seconds.
TIMESTAMP_TOLERANCE_SECONDS = 300

_INTEGER_RE = re.compile(r"^[+-]?[0-9]+$")
_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")

#: Headers that may carry an authentication digest, in lookup order.
_AUTH_HEADERS = ("x-pay-signature", "x-pay-receipt")

_REQUIRED_FIELDS = ("event_id", "account_id", "amount_minor", "currency")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    The result is a new dictionary holding ``event_id``, ``account_id``,
    ``amount_minor`` and ``currency`` taken from the received JSON object; any
    other request field is ignored.  ``InvalidNotification`` is raised for a
    notification that cannot be accepted.
    """
    body = _body_bytes(raw_body)
    key = _secret_bytes(secret)
    stamp = _timestamp(headers, now)
    payload = _json_object(body)
    schemes = _auth_schemes(headers)

    if not _authenticated(key, stamp, body, payload, schemes):
        raise InvalidNotification("notification signature did not verify")

    return _normalized_event(payload)


# --------------------------------------------------------------------------- #
# authentication
# --------------------------------------------------------------------------- #
def _authenticated(key, stamp, body, payload, schemes):
    """Return True when the delivery verifies via the v1 or the r0 path."""
    stamp_bytes = stamp.encode("ascii")

    # Current clients: HMAC over the timestamp and the exact received bytes.
    if _matches(key, stamp_bytes + b"." + body, schemes.get("v1")):
        return True

    # Legacy v0 receipts: HMAC over the timestamp and the event_id only.  Used
    # when the v1 body digest is missing or does not match, because the v0
    # relay may have reformatted the body in transit.
    event_id = payload.get("event_id")
    if isinstance(event_id, str) and event_id:
        receipt_message = stamp_bytes + b"." + event_id.encode("utf-8")
        if _matches(key, receipt_message, schemes.get("r0")):
            return True

    return False


def _matches(key, message, candidates):
    """Constant-time compare ``message``'s digest against every candidate."""
    if not candidates:
        return False
    expected = hmac.new(key, message, hashlib.sha256).hexdigest()
    expected_bytes = expected.encode("ascii")
    matched = False
    for candidate in candidates:
        provided = _ascii_bytes(candidate)
        if provided is not None and hmac.compare_digest(expected_bytes, provided):
            matched = True
    return matched


def _auth_schemes(headers):
    """Map lowercase signature scheme names to the hex digests offered for them.

    A header value may list several schemes (``v1=..., r0=...``), separated by
    commas and/or whitespace, so every token is considered.
    """
    schemes = {}
    for value in _header_values(headers, _AUTH_HEADERS):
        text = _text(value)
        if text is None:
            continue
        for token in re.split(r"[,\s]+", text.strip()):
            if "=" not in token:
                continue
            scheme, _, digest = token.partition("=")
            scheme = scheme.strip().lower()
            digest = digest.strip()
            if scheme and digest:
                schemes.setdefault(scheme, []).append(digest.lower())
    return schemes


# --------------------------------------------------------------------------- #
# request decoding and validation
# --------------------------------------------------------------------------- #
def _timestamp(headers, now):
    """Return the in-window delivery timestamp as ASCII text."""
    values = _header_values(headers, ("x-pay-timestamp",))
    stamp = _text(values[0]).strip() if values and _text(values[0]) else ""
    if not _INTEGER_RE.match(stamp):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")

    try:
        skew = abs(int(stamp) - float(now))
    except (OverflowError, TypeError, ValueError):
        raise InvalidNotification("unusable timestamp or clock reference")

    if skew > TIMESTAMP_TOLERANCE_SECONDS:
        raise InvalidNotification("timestamp outside the accepted window")
    return stamp


def _json_object(body):
    """Decode the received body as a JSON object."""
    try:
        payload = json.loads(body)
    except (UnicodeDecodeError, ValueError):
        raise InvalidNotification("body is not valid UTF-8 JSON")
    if not isinstance(payload, dict):
        raise InvalidNotification("body is not a JSON object")
    return payload


def _normalized_event(payload):
    """Validate required fields and build the worker's normalized dictionary."""
    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise InvalidNotification("notification is missing %r" % field)

    event_id = payload["event_id"]
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")

    account_id = payload["account_id"]
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")

    amount_minor = payload["amount_minor"]
    # bool is a subclass of int: booleans are not amounts.
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("amount_minor must be an integer")
    if amount_minor < 0:
        raise InvalidNotification("amount_minor must be nonnegative")

    currency = payload["currency"]
    if not isinstance(currency, str) or not _CURRENCY_RE.match(currency):
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


# --------------------------------------------------------------------------- #
# small helpers
# --------------------------------------------------------------------------- #
def _header_values(headers, names):
    """Collect values for ``names`` from a header mapping, ignoring case."""
    if headers is None:
        return []

    pairs = None
    get_items = getattr(headers, "items", None)
    if callable(get_items):
        try:
            pairs = list(get_items())
        except TypeError:
            pairs = None
    if pairs is None:
        try:
            pairs = list(headers)
        except TypeError:
            return []

    wanted = set(names)
    values = []
    for pair in pairs:
        name, value = _header_pair(pair)
        if name is not None and name in wanted:
            values.append(value)
    return values


def _header_pair(pair):
    """Normalize one header entry into a (lowercase name, value) tuple."""
    if isinstance(pair, str):
        name, sep, value = pair.partition(":")
        if not sep:
            return None, None
    else:
        try:
            name, value = pair
        except (TypeError, ValueError):
            return None, None
    name = _text(name)
    if name is None:
        return None, None
    return name.strip().lower(), value


def _text(value):
    """Return ``value`` as text, or None when it is not text-like."""
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value).decode("latin-1")
    return None


def _ascii_bytes(value):
    """Return ASCII bytes for ``value``, or None when it is not ASCII text."""
    text = _text(value)
    if text is None:
        return None
    try:
        return text.strip().encode("ascii")
    except UnicodeEncodeError:
        return None


def _body_bytes(raw_body):
    """Return the exact received body bytes."""
    if isinstance(raw_body, str):
        return raw_body.encode("utf-8")
    if isinstance(raw_body, (bytes, bytearray, memoryview)):
        return bytes(raw_body)
    raise InvalidNotification("request body is not bytes")


def _secret_bytes(secret):
    """Return the shared secret as bytes."""
    if isinstance(secret, str):
        return secret.encode("utf-8")
    if isinstance(secret, (bytes, bytearray, memoryview)):
        return bytes(secret)
    raise InvalidNotification("secret is not bytes")
