import hashlib
import hmac
import json
import unittest

from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

SECRET = b"public-test-provider-secret"
NOW = 1760000000


def v1_headers(event_body, stamp=str(NOW), secret=SECRET):
    digest = hmac.new(secret, stamp.encode() + b"." + event_body, hashlib.sha256).hexdigest()
    return {"X-Pay-Timestamp": stamp, "X-Pay-Signature": "v1=" + digest}


def receipt(stamp, event_id, secret=SECRET):
    return hmac.new(secret, stamp.encode() + b"." + event_id.encode("utf-8"),
                    hashlib.sha256).hexdigest()


class ReceiptPath(unittest.TestCase):
    def test_receipt_only_reformatted_body(self):
        # v0 relay reformatted the body: different bytes, no v1 digest.
        event = {"event_id": "evt-r0", "account_id": "客户-café", "amount_minor": 0,
                 "currency": "EUR", "provider_note": "café"}
        body = json.dumps(event, ensure_ascii=False, indent=2, sort_keys=True).encode()
        stamp = str(NOW)
        headers = {"X-Pay-Timestamp": stamp,
                   "X-Pay-Receipt": "r0=" + receipt(stamp, event["event_id"])}
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), {
            "event_id": "evt-r0", "account_id": "客户-café",
            "amount_minor": 0, "currency": "EUR"})

    def test_receipt_used_when_v1_mismatched(self):
        event = {"event_id": "evt-r1", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = v1_headers(body + b"tampered", stamp)
        headers["X-Pay-Receipt"] = "r0=" + receipt(stamp, event["event_id"])
        self.assertEqual(parse_payment(body, headers, SECRET, NOW)["event_id"], "evt-r1")

    def test_v1_still_preferred(self):
        event = {"event_id": "evt-r2", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        headers = v1_headers(body)
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)

    def test_receipt_wrong_secret(self):
        event = {"event_id": "evt-r3", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = {"X-Pay-Timestamp": stamp,
                   "X-Pay-Receipt": "r0=" + receipt(stamp, "evt-r3", b"other-secret")}
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW)

    def test_receipt_other_event_id(self):
        event = {"event_id": "evt-r4", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = {"X-Pay-Timestamp": stamp,
                   "X-Pay-Receipt": "r0=" + receipt(stamp, "evt-someone-else")}
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW)

    def test_receipt_stale_timestamp(self):
        event = {"event_id": "evt-r5", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=" + receipt(stamp, "evt-r5")}
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW + 301)

    def test_receipt_boundary_skew_ok(self):
        event = {"event_id": "evt-r6", "account_id": "acct", "amount_minor": 5,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW - 300)
        headers = {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=" + receipt(stamp, "evt-r6")}
        self.assertEqual(parse_payment(body, headers, SECRET, NOW)["amount_minor"], 5)

    def test_receipt_bad_fields_still_rejected(self):
        for broken in (
            {"event_id": "evt-r7", "account_id": "", "amount_minor": 5, "currency": "USD"},
            {"event_id": "evt-r7", "account_id": "a", "amount_minor": -1, "currency": "USD"},
            {"event_id": "evt-r7", "account_id": "a", "amount_minor": True, "currency": "USD"},
            {"event_id": "evt-r7", "account_id": "a", "amount_minor": 5.0, "currency": "USD"},
            {"event_id": "evt-r7", "account_id": "a", "amount_minor": 5, "currency": "usd"},
            {"event_id": "evt-r7", "account_id": "a", "amount_minor": 5, "currency": "USDD"},
            {"event_id": "evt-r7", "account_id": "a", "currency": "USD"},
        ):
            body = json.dumps(broken).encode()
            stamp = str(NOW)
            headers = {"X-Pay-Timestamp": stamp,
                       "X-Pay-Receipt": "r0=" + receipt(stamp, "evt-r7")}
            with self.assertRaises(InvalidNotification, msg=broken):
                parse_payment(body, headers, SECRET, NOW)

    def test_no_credentials(self):
        body = json.dumps({"event_id": "e", "account_id": "a", "amount_minor": 1,
                           "currency": "USD"}).encode()
        with self.assertRaises(InvalidNotification):
            parse_payment(body, {"X-Pay-Timestamp": str(NOW)}, SECRET, NOW)
        with self.assertRaises(InvalidNotification):
            parse_payment(body, {}, SECRET, NOW)
        with self.assertRaises(InvalidNotification):
            parse_payment(body, None, SECRET, NOW)

    def test_malformed_inputs(self):
        stamp = str(NOW)
        good = {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=" + receipt(stamp, "e")}
        with self.assertRaises(InvalidNotification):
            parse_payment(b"{not json", good, SECRET, NOW)
        with self.assertRaises(InvalidNotification):
            parse_payment(b"[1,2,3]", good, SECRET, NOW)
        with self.assertRaises(InvalidNotification):
            parse_payment(b"", good, SECRET, NOW)
        with self.assertRaises(InvalidNotification):
            parse_payment(b'{"event_id": "e"}',
                          {"X-Pay-Timestamp": "nope", "X-Pay-Receipt": "r0=x"}, SECRET, NOW)

    def test_header_case_and_multi_scheme_and_str_secret(self):
        event = {"event_id": "evt-r8", "account_id": "acct", "amount_minor": 12,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = {"x-pay-timestamp": stamp,
                   "X-PAY-SIGNATURE": "v1=deadbeef, r0=" + receipt(stamp, "evt-r8").upper()}
        self.assertEqual(parse_payment(body, headers, SECRET.decode(), NOW), event)

    def test_tuple_headers_and_uppercase_digest(self):
        event = {"event_id": "evt-r9", "account_id": "acct", "amount_minor": 1,
                 "currency": "USD"}
        body = json.dumps(event).encode()
        stamp = str(NOW)
        headers = [("X-Pay-Timestamp", stamp),
                   ("X-Pay-Receipt", "r0=" + receipt(stamp, "evt-r9").upper())]
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)


if __name__ == "__main__":
    unittest.main()
